import 'package:flutter/material.dart';
import '../widgets/campo_texto.dart';
import 'registro_screen.dart';

class LoginScreen extends StatefulWidget {
  const LoginScreen({super.key});

    @override
      State<LoginScreen> createState() => _LoginScreenState();
      }

      class _LoginScreenState extends State<LoginScreen> {
        final _formKey = GlobalKey<FormState>();
          final _correoController = TextEditingController();
            final _claveController = TextEditingController();
              bool _cargando = false;
                String? _mensajeError;

                  @override
                    void dispose() {
                        _correoController.dispose();
                            _claveController.dispose();
                                super.dispose();
                                  }

                                    String? _validarCorreo(String? valor) {
                                        final texto = valor?.trim() ?? '';
                                            final formato = RegExp(r'^[^@\s]+@[^@\s]+\.[^@\s]+$');
                                                if (!formato.hasMatch(texto)) return 'Escribe un correo válido';
                                                    return null;
                                                      }

                                                        String? _validarClave(String? valor) {
                                                            if (valor == null || valor.length < 8) {
                                                                  return 'La contraseña debe tener al menos 8 caracteres';
                                                                      }
                                                                          return null;
                                                                            }

                                                                              Future<void> _irARegistro() async {
                                                                                  final correo = await Navigator.push<String>(
                                                                                        context,
                                                                                              MaterialPageRoute(builder: (_) => const RegistroScreen()),
                                                                                                  );
                                                                                                      if (!mounted) return;
                                                                                                          if (correo != null) {
                                                                                                                _correoController.text = correo;
                                                                                                                    }
                                                                                                                      }

                                                                                                                        Future<void> _iniciarSesion() async {
                                                                                                                            if (!_formKey.currentState!.validate()) return;
                                                                                                                                setState(() {
                                                                                                                                      _cargando = true;
                                                                                                                                            _mensajeError = null;
                                                                                                                                                });
                                                                                                                                                    await Future.delayed(const Duration(seconds: 2));
                                                                                                                                                        if (!mounted) return;
                                                                                                                                                            final correcta = _claveController.text == '12345678';
                                                                                                                                                                setState(() {
                                                                                                                                                                      _cargando = false;
                                                                                                                                                                            _mensajeError = correcta ? null : 'Correo o contraseña incorrectos';
                                                                                                                                                                                });
                                                                                                                                                                                  }

                                                                                                                                                                                    @override
                                                                                                                                                                                      Widget build(BuildContext context) {
                                                                                                                                                                                          return Scaffold(
                                                                                                                                                                                                appBar: AppBar(title: const Text('Iniciar sesión')),
                                                                                                                                                                                                      body: SingleChildScrollView(
                                                                                                                                                                                                              padding: const EdgeInsets.all(24),
                                                                                                                                                                                                                      child: Form(
                                                                                                                                                                                                                                key: _formKey,
                                                                                                                                                                                                                                          child: Column(
                                                                                                                                                                                                                                                      children: [
                                                                                                                                                                                                                                                                    CampoTexto(
                                                                                                                                                                                                                                                                                    etiqueta: 'Correo',
                                                                                                                                                                                                                                                                                                    controlador: _correoController,
                                                                                                                                                                                                                                                                                                                    validador: _validarCorreo,
                                                                                                                                                                                                                                                                                                                                    teclado: TextInputType.emailAddress,
                                                                                                                                                                                                                                                                                                                                                  ),
                                                                                                                                                                                                                                                                                                                                                                const SizedBox(height: 16),
                                                                                                                                                                                                                                                                                                                                                                              CampoTexto(
                                                                                                                                                                                                                                                                                                                                                                                              etiqueta: 'Contraseña',
                                                                                                                                                                                                                                                                                                                                                                                                              controlador: _claveController,
                                                                                                                                                                                                                                                                                                                                                                                                                              validador: _validarClave,
                                                                                                                                                                                                                                                                                                                                                                                                                                              oculto: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const SizedBox(height: 16),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (_mensajeError != null)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Text(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          _mensajeError!,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            style: const TextStyle(color: Colors.red),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const SizedBox(height: 16),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ElevatedButton(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        onPressed: _cargando ? null : _iniciarSesion,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        child: _cargando
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ? const SizedBox(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    height: 20,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            width: 20,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    child: CircularProgressIndicator(strokeWidth: 2),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              : const Text('Entrar'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          TextButton(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onPressed: _irARegistro,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          child: const Text('¿No tienes cuenta? Regístrate'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }